arguments.command:
python -c "
import numpy as np, os, collections
e=np.load('data/beh/Imaging_Exp_info.npy',allow_pickle=1).item()
bad=[]
for et in e:
    B=np.load('data/beh/Beh_%s.npy'%et,allow_pickle=1).item()
    for d in e[et]:
        key='%s_%s_%s'%(d['mname'],d['datexp'],d['blk']); kn=key+('_%s'%d['stimtype'] if 'stimtype' in d else '')
        b=B[kn]; wn=np.asarray(b['WallName'],str); isr=b['isRew']
        cohort=d.get('exptype','naive')
        if isr.sum()==0:
            if cohort=='sup': print('SUP with no reward', key, et)
            continue
        rw=np.unique(wn[isr])
        cat=[int(c) for w,c in zip(b['UniqWalls'],np.asarray(b['stim_id'],float)) if str(w) in rw and not np.isnan(c)]
        if len(rw)!=1 or cat!=[2]: bad.append((key,et,cohort,list(rw),cat))
        if cohort!='sup': print('non-sup with reward!', key, et, cohort)
    del B
print('bad:',bad)
"

